class Solution {
    public int countCollisions(String directions){
        int left=0,right=directions.length()-1;
        while(left<=right&&directions.charAt(left)=='L')left++;
        while(left<=right&&directions.charAt(right)=='R')right--;
        int answer=0;
        for(int i=left;i<=right;i++)if(directions.charAt(i)!='S')answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countCollisions(directions:String):Int{
        var left=0;
        var right=directions.lastIndex;
        while(left<=right&&directions[left]=='L')left++;
        while(left<=right&&directions[right]=='R')right--;
        var answer=0;
        for(i in left..right)if(directions[i]!='S')answer++;
        return answer
    }
}

